import os,re,collections
root='AlgebraicJacobian'
def path(mod):
    return mod.replace('.','/')+'.lean'
imports={}
for dp,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mod=p[:-5].replace('/','.')
            imps=re.findall(r'^import\s+(\S+)',open(p).read(),re.M)
            imports[mod]=imps
start='AlgebraicJacobian.Picard.DivisorFamilyAffFieldMono'
seen=set();st=[start]
while st:
    m=st.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports.get(m,[]):
        if i.startswith('AlgebraicJacobian') and i not in seen: st.append(i)
print("closure size (AJ modules):",len(seen))
for probe in ['AlgebraicJacobian.Picard.DivisorFamilyFieldSurj','AlgebraicJacobian.Picard.DivisorFamilyFieldEquiv','AlgebraicJacobian.Picard.DivSchemeMonoBridgeField','AlgebraicJacobian.Picard.DivSchemeMonoBridgeRel','AlgebraicJacobian.Picard.DivRepClassifyZarSep','AlgebraicJacobian.Picard.DivisorFamilyAffClassDegree','AlgebraicJacobian.Picard.DivisorFamilyAffZar','AlgebraicJacobian.Picard.DivisorFamilyAffCompare','AlgebraicJacobian.Picard.DivisorFamilyAffStalkEval','AlgebraicJacobian.Picard.DivSchemeMono','AlgebraicJacobian.Picard.DivisorStalkIdeal','AlgebraicJacobian.Picard.DivisorFamilyWindow','AlgebraicJacobian.Picard.DivisorFamilyEpsMono','AlgebraicJacobian.Picard.DivisorFamilyFieldDictionary']:
